//! Systems declared `on_load` also run once when a scene loads, before the
//! first tick. Found when Kevin played Delve: its floor is generated by a
//! `sim` system, stages run on ticks, and a discrete clock ticks on the
//! first key, so the window showed an empty screen until then.

use argus_ecs::{Event, World};
use argus_sim::{Scheduler, SchedulerConfig, Stage, SystemDesc};
use std::cell::RefCell;
use std::rc::Rc;

#[test]
fn on_load_systems_run_once_before_the_first_tick_in_stage_order() {
    let mut w = World::new();
    argus_ecs::hierarchy::register(&mut w).unwrap();
    let mut s = Scheduler::new(SchedulerConfig::discrete().seed(3));
    let ran: Rc<RefCell<Vec<(String, u64)>>> = Rc::new(RefCell::new(Vec::new()));
    let add = |s: &mut Scheduler, desc: SystemDesc| {
        let log = ran.clone();
        let name = desc.name.clone();
        s.add_system(
            desc,
            Box::new(move |ctx| {
                log.borrow_mut().push((name.clone(), ctx.tick));
                ctx.emit("ran", vec![]);
                Ok(())
            }),
        )
        .unwrap();
    };
    // Declared late-stage first, so the order comes from the stages.
    add(
        &mut s,
        SystemDesc::new("late.decorate", Stage::Late).on_load(),
    );
    add(
        &mut s,
        SystemDesc::new("sim.generate", Stage::Sim).on_load(),
    );
    add(&mut s, SystemDesc::new("sim.turn", Stage::Sim));
    add(&mut s, SystemDesc::new("sim.off", Stage::Sim).on_load());
    s.disable("sim.off", "switched off").unwrap();

    assert_eq!(s.run_load(&mut w).unwrap(), 2);
    assert_eq!(
        *ran.borrow(),
        vec![("sim.generate".into(), 0), ("late.decorate".into(), 0)],
        "the flagged, enabled systems, in stage order, and nothing else"
    );
    assert_eq!(s.tick(), 0, "no turn was taken");
    let events = w.drain_events();
    let ran_by: Vec<(u64, Option<String>)> = events
        .iter()
        .filter(|r| matches!(&r.event, Event::Game { name, .. } if name == "ran"))
        .map(|r| (r.frame, r.by.as_deref().map(str::to_string)))
        .collect();
    assert_eq!(
        ran_by,
        vec![
            (0, Some("sim.generate".into())),
            (0, Some("late.decorate".into()))
        ],
        "what they emit is frame 0 and says who"
    );

    // The first turn runs every system in its stage, the flagged ones again.
    ran.borrow_mut().clear();
    s.advance(&mut w, 1).unwrap();
    let names: Vec<String> = ran.borrow().iter().map(|r| r.0.clone()).collect();
    assert_eq!(names, vec!["sim.generate", "sim.turn", "late.decorate"]);
    assert_eq!(s.tick(), 1);
}
